sealed class SpellIssue{internal int Start,Length;internal string Word,Replacement;}
static class WindowsSpelling {
 static IWindowsSpellFactory factory;static readonly Dictionary<string,IWindowsSpellChecker> checkers=new Dictionary<string,IWindowsSpellChecker>();internal static string Error="";internal static string[] Languages(){try{if(factory==null)factory=(IWindowsSpellFactory)Activator.CreateInstance(Type.GetTypeFromCLSID(new Guid("7AB36653-1796-484B-BDFA-E74F1DB7C1DC")));IEnumString values;factory.Languages(out values);return Strings(values,100);}catch(Exception e){Error=e.Message;return new string[0];}}
 static string[] Strings(IEnumString value,int max){var list=new List<string>();IntPtr count=Marshal.AllocCoTaskMem(4);try{var word=new string[1];while(list.Count<max&&value.Next(1,word,count)==0)list.Add(word[0]);}finally{Marshal.FreeCoTaskMem(count);if(value!=null)Marshal.ReleaseComObject(value);}return list.ToArray();}
 internal static string DefaultLanguage(string requested){var languages=Languages();if(languages.Contains(requested))return requested;string current=CultureInfo.CurrentUICulture.Name;return languages.FirstOrDefault(x=>x.Equals(current,StringComparison.OrdinalIgnoreCase))??languages.FirstOrDefault(x=>x.StartsWith("en-",StringComparison.OrdinalIgnoreCase))??languages.FirstOrDefault();}
 static IWindowsSpellChecker Get(string language){if(language==null)throw new Exception("Windows has no spellchecking language installed. Add a language in Windows Settings, or turn spelling off.");IWindowsSpellChecker c;if(!checkers.TryGetValue(language,out c)){factory.Create(language,out c);checkers[language]=c;}return c;}
 internal static List<SpellIssue> Check(string text,string language){var list=new List<SpellIssue>();if(text.Length==0)return list;var checker=Get(DefaultLanguage(language));IWindowsSpellErrors errors;checker.Check(text,out errors);try{IWindowsSpellError error;while(list.Count<128&&errors.Next(out error)==0&&error!=null){try{uint at,length;int action;string replacement;error.Start(out at);error.Length(out length);error.Action(out action);error.Replacement(out replacement);if(action!=0&&length>0&&at+length<=text.Length)list.Add(new SpellIssue{Start=(int)at,Length=(int)length,Word=text.Substring((int)at,(int)length),Replacement=replacement});}finally{Marshal.ReleaseComObject(error);}}}finally{Marshal.ReleaseComObject(errors);}return list;}
 internal static string[] Suggestions(string word,string language){IEnumString values;Get(DefaultLanguage(language)).Suggest(word,out values);return Strings(values,7);}
 internal static void Ignore(string word,string language){Get(DefaultLanguage(language)).Ignore(word);}internal static void Add(string word,string language){Get(DefaultLanguage(language)).Add(word);}
}
sealed class SpellTextBox:RichTextBox {
 internal bool SolidGlyphs;readonly System.Windows.Forms.Timer timer=new System.Windows.Forms.Timer{Interval=1200};internal readonly List<SpellIssue> Issues=new List<SpellIssue>();internal string SpellLanguage="",SpellStatus="",Placeholder="";bool spellEnabled;internal int Insets=0;[DllImport("user32.dll")]static extern IntPtr SendMessage(IntPtr window,int msg,IntPtr w,ref Native.RECT rect);internal void SetInsets(int n){Insets=n;SetTextRect();}void SetTextRect(){if(!IsHandleCreated||!Multiline||Insets<=0)return;var rect=new Native.RECT{Left=Insets,Top=Insets,Right=ClientSize.Width-Insets,Bottom=ClientSize.Height-Insets};SendMessage(Handle,0xB3,IntPtr.Zero,ref rect);}
 protected override void OnHandleCreated(EventArgs e){base.OnHandleCreated(e);SetTextRect();}protected override void OnResize(EventArgs e){base.OnResize(e);SetTextRect();}internal Action<ContextMenuStrip> ThemeMenu;internal Action<ContextMenuStrip> FormatMenu;internal ContextMenuStrip editMenu;
 internal bool SpellEnabled{get{return spellEnabled;}set{spellEnabled=value;timer.Stop();Issues.Clear();if(value)timer.Start();Invalidate();}}
 internal SpellTextBox(){TextChanged+=(s,e)=>{Issues.Clear();timer.Stop();if(spellEnabled)timer.Start();Invalidate();};SelectionChanged+=(s,e)=>Invalidate();VScroll+=(s,e)=>Invalidate();HScroll+=(s,e)=>Invalidate();timer.Tick+=(s,e)=>{timer.Stop();CheckNow();};Disposed+=(s,e)=>{timer.Dispose();if(editMenu!=null)editMenu.Dispose();};MouseUp+=(s,e)=>{if(e.Button==MouseButtons.Right)ShowSpellingMenu(e.Location);};}
 internal void CheckNow(){Issues.Clear();if(!spellEnabled)return;try{int start=Math.Max(0,GetCharIndexFromPosition(Point.Empty)-2000),length=Math.Min(32000,TextLength-start);string input=Text.Substring(start,length);foreach(var issue in WindowsSpelling.Check(input,SpellLanguage)){issue.Start+=start;Issues.Add(issue);}SpellStatus=Issues.Count+" possible spelling corrections";}catch(Exception e){SpellStatus=e.Message;}Invalidate();}
 internal void ReplaceIssue(SpellIssue issue,string replacement){if(issue.Start+issue.Length>TextLength||Text.Substring(issue.Start,issue.Length)!=issue.Word)return;Select(issue.Start,issue.Length);SelectedText=replacement;Focus();}
 internal void ShowSpellingMenu(Point point){bool fresh=editMenu==null||editMenu.IsDisposed;if(fresh)editMenu=new ContextMenuStrip();var menu=editMenu;menu.Items.Clear();int at=GetCharIndexFromPosition(point);var issue=Issues.FirstOrDefault(x=>at>=x.Start&&at<x.Start+x.Length);if(issue!=null){try{string[] choices=WindowsSpelling.Suggestions(issue.Word,SpellLanguage);if(!String.IsNullOrEmpty(issue.Replacement))choices=new[]{issue.Replacement}.Concat(choices).Distinct().ToArray();if(choices.Length==0)menu.Items.Add("No suggestion").Enabled=false;foreach(string suggestion in choices){string value=suggestion;menu.Items.Add(value,null,(s,e)=>ReplaceIssue(issue,value));}menu.Items.Add("Ignore word",null,(s,e)=>{WindowsSpelling.Ignore(issue.Word,SpellLanguage);CheckNow();});menu.Items.Add("Add to Windows dictionary",null,(s,e)=>{WindowsSpelling.Add(issue.Word,SpellLanguage);CheckNow();});menu.Items.Add(new ToolStripSeparator());}catch{}}menu.Items.Add("Undo",null,(s,e)=>Undo());menu.Items.Add("Cut",null,(s,e)=>Cut());menu.Items.Add("Copy",null,(s,e)=>Copy());menu.Items.Add("Paste",null,(s,e)=>Paste());menu.Items.Add("Select all",null,(s,e)=>SelectAll());if(FormatMenu!=null)FormatMenu(menu);if(ThemeMenu!=null)ThemeMenu(menu);menu.Show(this,point);}
 protected override void WndProc(ref Message m){base.WndProc(ref m);if(m.Msg==0xF&&SolidGlyphs)SolidText.Paint(this,i=>Font);if(m.Msg==0xF&&!SolidGlyphs&&TextLength==0&&!Focused&&Placeholder.Length>0)try{using(var g=Graphics.FromHwnd(Handle))TextRenderer.DrawText(g,Placeholder,Font,new Rectangle(4,4,Width-8,Height-8),Color.FromArgb(130,ForeColor),TextFormatFlags.EndEllipsis);}catch{}if(m.Msg!=0xF||!spellEnabled||Issues.Count==0||!IsHandleCreated)return;try{using(var g=Graphics.FromHwnd(Handle))using(var pen=new Pen(Color.FromArgb(213,91,83),1)){g.SetClip(ClientRectangle);foreach(var issue in Issues){Point first=GetPositionFromCharIndex(issue.Start);if(first.Y<-Font.Height||first.Y>Height)continue;int end=issue.Start+issue.Length;Point a=first;for(int i=issue.Start+1;i<=end;i++){Point b=GetPositionFromCharIndex(i);if(b.Y!=a.Y||i==end){int right=b.Y==a.Y?b.X:ClientSize.Width-3;int y=a.Y+Font.Height-2;for(int x=a.X;x<right-1;x+=4){g.DrawLine(pen,x,y,x+2,y+2);g.DrawLine(pen,x+2,y+2,x+4,y);}a=b;}}}}}catch{}}
}
